import React, { useEffect } from 'react';

const MinimalPortfolio = () => {
  useEffect(() => {
    // Set page title
    document.title = 'RD/> Portfolio - Main';
  }, []);

  return (
    <div style={styles.container}>
      {/* Main Content */}
      <h2 style={styles.name}>Ranvir Deshmukh</h2>
      <h3 style={styles.tagline}>I write software and make videos.</h3>

      <p style={styles.description}>
        I’m currently building{' '}
        <a
          href="https://courseme.ai"
          target="_blank"
          rel="noopener noreferrer"
          style={{
            textDecoration: 'none',
            color: '#571ce0',
            fontWeight: 600
          }}
        >
          CourseMe
        </a>
        <span style={{ color: '#FD5E53', fontWeight: 600 }}>.</span> <br />
        Studying Computer Science at Dartmouth. <br />
        Reach out — I’m always open to chat!
      </p>

      <div style={styles.linkContainer}>
        <a
          href="https://www.linkedin.com/in/ranvir-deshmukh-209706199/"
          style={styles.linkStyle}
          target="_blank"
          rel="noopener noreferrer"
        >
          LinkedIn
        </a>
        <span style={styles.linkSeparator}>|</span>
        <a
          href="https://github.com/Ranvirdeshmukh"
          style={styles.linkStyle}
          target="_blank"
          rel="noopener noreferrer"
        >
          GitHub
        </a>
      </div>

      {/* Subtle Logo in Bottom-Right Corner */}
      <div style={styles.bottomLogo}>
        RD/&gt;
      </div>
    </div>
  );
};

const styles = {
  container: {
    backgroundColor: '#FFFFFF',
    color: '#000000',
    minHeight: '100vh',
    fontFamily: "'SF Pro Display', sans-serif",
    fontWeight: 500,

    // Make it left-aligned
    margin: '0',
    padding: '0 20px',
    maxWidth: '600px',
    position: 'relative',  // Important for absolutely positioning the logo
    textAlign: 'left',     // Explicitly left-aligns text
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'flex-start',  // Left alignment
    // Removing justifyContent: 'center' so content starts near the top
  },
  name: {
    fontSize: '32px',
    margin: '0 0 10px 0',
    fontWeight: 500,
  },
  tagline: {
    fontSize: '20px',
    margin: '0 0 25px 0',
    opacity: 0.8,
  },
  description: {
    fontSize: '16px',
    lineHeight: '1.6',
    marginBottom: '30px',
  },
  linkContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    marginBottom: '40px',
  },
  linkStyle: {
    textDecoration: 'none',
    color: '#000000',
    fontWeight: 500,
  },
  linkSeparator: {
    color: '#000000',
    opacity: 0.6,
  },
  bottomLogo: {
    position: 'absolute',
    bottom: '20px',
    right: '20px',
    fontSize: '14px',
    fontWeight: 600,
    color: '#999999',  // Slightly gray for a subtle look
    opacity: 0.8,
  }
};

export default MinimalPortfolio;
